type Need { item: Str, qty: Int }

type Order { id: Str, needs: List[Need] }

fn stock_level(stock: Map[Str, Int], name: Str) -> Int {
  return stock.get(name).unwrap_or(0)
}

fn parse_item(text: Str, stock: Map[Str, Int]) -> Option[Need] {
  let parts = text.split(":")
  if parts.len() != 2 {
    return None
  }
  let name = parts.get_or(0, "")
  let qty_text = parts.get_or(1, "")
  if name.is_empty() or qty_text.is_empty() or not qty_text.is_numeric() {
    return None
  }
  let qty = qty_text.to_int().unwrap_or(0)
  if qty <= 0 or not stock.has(name) {
    return None
  }
  return Some(Need { item: name, qty: qty })
}

fn parse_items(pieces: List[Str], stock: Map[Str, Int]) -> Option[List[Need]] {
  if pieces.is_empty() {
    let none: List[Need] = []
    return Some(none)
  }
  let head = parse_item(text: pieces.first().unwrap_or(""), stock: stock)?
  let rest = parse_items(pieces: pieces.drop(1), stock: stock)?
  return Some(rest.push(head))
}

fn parse_order(text: Str, stock: Map[Str, Int]) -> Result[Order, Str] {
  let sp = text.split(" ")
  let id = sp.get_or(0, "")
  let bad = "bad order " + id
  if sp.len() != 2 or id.is_empty() {
    return Err(bad)
  }
  let needs = parse_items(pieces: sp.get_or(1, "").split(","), stock: stock).ok_or(bad)?
  return Ok(Order { id: id, needs: needs })
}

fn can_fill(needs: List[Need], stock: Map[Str, Int]) -> Bool {
  return needs.all(fn(n) => (needs.filter(fn(m) => m.item == n.item).fold(0, fn(acc, m) => acc + m.qty)) <= stock_level(stock: stock, name: n.item))
}

fn take_items(needs: List[Need], stock: Map[Str, Int]) -> Map[Str, Int] {
  return needs.fold(stock, fn(st, n) => st.set(n.item, stock_level(stock: st, name: n.item) - n.qty))
}

fn fill(orders: List[Str], stock: Map[Str, Int], filled: List[Str]) -> Result[List[Str], Str] {
  if orders.is_empty() {
    return Ok(filled)
  }
  let current = parse_order(text: orders.first().unwrap_or(""), stock: stock)?
  if can_fill(needs: current.needs, stock: stock) {
    let left = take_items(needs: current.needs, stock: stock)
    return fill(orders: orders.drop(1), stock: left, filled: filled.push(current.id))
  }
  return fill(orders: orders.drop(1), stock: stock, filled: filled)
}

pub fn inventory(orders: List[Str], stock: Map[Str, Int]) -> Result[List[Str], Str] {
  let none: List[Str] = []
  return fill(orders: orders, stock: stock, filled: none)
}
